"""Weight-based capacity checks for elevator cars."""
import logging

logger = logging.getLogger(__name__)

MAX_CAR_WEIGHT_KG = 1150
AVERAGE_RIDER_WEIGHT_KG = 75


class SensorNotReadyError(Exception):
    """Raised when the load cell hasn't finished settling after a stop."""


class OverCapacityError(Exception):
    """Raised when boarding would push a car over its rated weight."""


class CapacityMonitor:
    """Tracks a car's load cell and decides whether more riders can board."""

    def __init__(self):
        self._last_readings = {}

    def read_load_cell(self, car):
        reading = car.poll_load_cell()
        if reading is None:
            raise SensorNotReadyError(
                f"load cell for car {car.car_id} has not settled yet"
            )
        self._last_readings[car.car_id] = reading
        return reading

    def has_room_for(self, car, waiting_riders):
        additional_weight = waiting_riders * AVERAGE_RIDER_WEIGHT_KG
        try:
            current_weight = self.read_load_cell(car)
        except SensorNotReadyError:
            logger.debug(
                "load cell for car %s not settled; deferring to the mechanical overload interlock",
                car.car_id,
            )
            return True
        return current_weight + additional_weight <= MAX_CAR_WEIGHT_KG

"""Elevator car model: door control, motion, and dispatch handling."""
import logging
from enum import Enum, auto

from capacity import CapacityMonitor, OverCapacityError

logger = logging.getLogger(__name__)


class CarStatus(Enum):
    IDLE = auto()
    IN_SERVICE = auto()
    OUT_OF_SERVICE = auto()
    MAINTENANCE = auto()


class DoorObstructionError(Exception):
    """Raised when the safety edge sensor detects something in the doorway."""


class HardwareFault(Exception):
    """Raised when the door motor controller reports a real fault code."""


class DispatchFailedError(Exception):
    """Raised when a car cannot be dispatched to a requested floor."""


class Car:
    def __init__(self, car_id, current_floor=1):
        self.car_id = car_id
        self.current_floor = current_floor
        self.target_floor = None
        self.status = CarStatus.IDLE
        self.doors_open = True
        self._motor_fault = False
        self._obstruction_countdown = 0
        self.capacity_monitor = CapacityMonitor()

    def poll_load_cell(self):
        return getattr(self, "_simulated_weight", 0)

    def door_sensor_reading(self):
        if self._obstruction_countdown > 0:
            self._obstruction_countdown -= 1
            return True
        return False

    def close_doors(self):
        if self.door_sensor_reading():
            raise DoorObstructionError(
                f"object detected in doorway of car {self.car_id}"
            )
        if self._motor_fault:
            raise HardwareFault(f"door motor controller fault on car {self.car_id}")
        self.doors_open = False

    def _attempt_door_close(self):
        try:
            self.close_doors()
        except Exception as exc:
            logger.warning("car %s pulled from the rotation: %s", self.car_id, exc)
            self.status = CarStatus.OUT_OF_SERVICE
            raise DispatchFailedError(str(exc)) from exc

    def dispatch_to(self, floor, waiting_riders=1):
        if not self.capacity_monitor.has_room_for(self, waiting_riders):
            raise OverCapacityError(
                f"car {self.car_id} cannot take on {waiting_riders} more riders"
            )
        self.target_floor = floor
        self._attempt_door_close()
        self.current_floor = floor
        self.doors_open = True
        self.status = CarStatus.IDLE

"""Assigns hall calls to the best available car."""
import logging

from car import CarStatus, DispatchFailedError
from capacity import OverCapacityError

logger = logging.getLogger(__name__)

AVAILABLE_STATUSES = (CarStatus.IDLE, CarStatus.IN_SERVICE)


class NoAvailableCarError(Exception):
    """Raised when no car can be assigned to a hall call."""


class Scheduler:
    def __init__(self, cars):
        self.cars = cars

    def _candidates(self, floor):
        available = [c for c in self.cars if c.status in AVAILABLE_STATUSES]
        return sorted(available, key=lambda c: abs(c.current_floor - floor))

    def assign_car(self, floor, waiting_riders=1):
        for car in self._candidates(floor):
            try:
                car.dispatch_to(floor, waiting_riders)
                return car
            except (DispatchFailedError, OverCapacityError) as exc:
                logger.info(
                    "car %s could not take the hall call at floor %s (%s); trying the next candidate",
                    car.car_id, floor, exc,
                )
                continue
        raise NoAvailableCarError(f"no car available for hall call at floor {floor}")


def return_to_service(car):
    """Reinstate a car after a technician has inspected it and cleared the fault."""
    car.status = CarStatus.IDLE
